from pathlib import Path
import subprocess, sys

ROOT = Path.cwd()
EXPECTED_PREFIX = '828c12b'

def fail(message):
    print(f'\nERROR: {message}\n')
    sys.exit(1)

head = subprocess.check_output(['git','rev-parse','HEAD'], cwd=ROOT, text=True).strip()
if not head.startswith(EXPECTED_PREFIX):
    fail(f'This patch targets {EXPECTED_PREFIX}, but current HEAD is {head}.')

player_path = ROOT / 'app/(portal)/game/components/RoomMusicPlayer.tsx'
mobile_path = ROOT / 'components/portal/mobile-portal-navigation.tsx'
forum_path = ROOT / 'components/portal/forum-sidebar-menu.tsx'
route_path = ROOT / 'app/api/music/current/route.ts'
for p in [player_path, mobile_path, forum_path]:
    if not p.exists(): fail(f'Missing expected file: {p.relative_to(ROOT)}')
if route_path.exists(): fail('app/api/music/current/route.ts already exists.')

player = player_path.read_text(encoding='utf-8')
mobile = mobile_path.read_text(encoding='utf-8')
forum = forum_path.read_text(encoding='utf-8')

# Strict preflight: confirm this is the just-tested state.
required_player = ['createPortal', 'Location Music', 'game-music-context-slot', 'needsGesture']
for needle in required_player:
    if needle not in player: fail(f'Unexpected RoomMusicPlayer state; missing {needle}.')
if 'People & Character' in mobile or "Sepulchria's People\n" in mobile:
    fail('Mobile duplicate People section appears to have returned; refusing to guess.')
if 'mobile?: boolean;' not in forum:
    fail('Expected current Forum mobile variant is missing.')

# Prepare mobile changes in memory.
old_entry = 'className="min-w-0 flex-1 truncate text-[11px] text-[rgb(var(--sep-colour-b8a98f))]"'
new_entry = 'className="min-w-0 flex-1 truncate text-[10px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-b8a98f))]"'
if mobile.count(old_entry) != 1: fail(f'EntryButton label anchor count was {mobile.count(old_entry)}, expected 1.')
mobile = mobile.replace(old_entry, new_entry, 1)

for label in ['Rules', 'Economy & Crafting', 'Legal & Safety']:
    marker = f'>{label}<'
    # Content is multiline, so validate the visible label separately.
    if label not in mobile: fail(f'Missing mobile label {label}.')

mobile = mobile.replace('className="min-w-0 flex-1 truncate text-[11px] text-[rgb(var(--sep-colour-b8a98f))]">\n                          Rules', 'className="min-w-0 flex-1 truncate text-[10px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-b8a98f))]">\n                          Rules', 1)
mobile = mobile.replace('className="min-w-0 flex-1 truncate text-[11px] text-[rgb(var(--sep-colour-b8a98f))]">\n                          Economy & Crafting', 'className="min-w-0 flex-1 truncate text-[10px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-b8a98f))]">\n                          Economy & Crafting', 1)
mobile = mobile.replace('className="min-w-0 flex-1 text-[11px] text-[rgb(var(--sep-colour-b8a98f))]">\n                        Legal & Safety', 'className="min-w-0 flex-1 text-[10px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-b8a98f))]">\n                        Legal & Safety', 1)

bottom_map = {'<span>Aureth</span>':'<span className="uppercase tracking-[0.14em]">AURETH</span>', '<span>Enter</span>':'<span className="uppercase tracking-[0.14em]">ENTER</span>', '<span>People</span>':'<span className="uppercase tracking-[0.14em]">PEOPLE</span>', '<span>Messages</span>':'<span className="uppercase tracking-[0.14em]">MESSAGES</span>', '<span>More</span>':'<span className="uppercase tracking-[0.14em]">MORE</span>'}
for old, new in bottom_map.items():
    if mobile.count(old) != 1: fail(f'Bottom label anchor {old} count was {mobile.count(old)}, expected 1.')
    mobile = mobile.replace(old, new, 1)

# Forum's mobile-only label must match the same uppercase vocabulary.
old_forum = 'mobile ? "min-w-0 flex-1 truncate text-[11px] text-[rgb(var(--sep-colour-b8a98f))]" : "truncate"'
new_forum = 'mobile ? "min-w-0 flex-1 truncate text-[10px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-b8a98f))]" : "truncate"'
if forum.count(old_forum) != 1: fail('Forum mobile label anchor not found exactly once.')
forum = forum.replace(old_forum, new_forum, 1)

print('Preflight passed. Applying music/mobile fixes...')
player_path.write_text('"use client";\n\nimport {\n  useEffect,\n  useMemo,\n  useRef,\n  useState,\n} from "react";\nimport { createPortal } from "react-dom";\nimport {\n  ChevronDown,\n  Pause,\n  Play,\n  Volume2,\n  VolumeX,\n} from "lucide-react";\n\nimport type {\n  CharacterMusicPayload,\n  PlayableMusicTrack,\n} from "@/lib/music/get-character-music";\n\ntype Props = CharacterMusicPayload & {\n  locationName: string;\n};\n\ntype CurrentMusicResponse = {\n  locationName: string | null;\n  music: CharacterMusicPayload | null;\n};\n\nconst LIVE_CHECK_MS = 4_000;\n\nfunction positionKey(trackId: string) {\n  return `sepulchria:location-music-position:${trackId}`;\n}\n\nexport default function RoomMusicPlayer({\n  locationName: initialLocationName,\n  locationTrack: initialLocationTrack,\n  ownedTracks: initialOwnedTracks,\n  preferences,\n}: Props) {\n  const audioRef =\n    useRef<HTMLAudioElement | null>(\n      null,\n    );\n\n  const fadeTimerRef =\n    useRef<number | null>(null);\n\n  const lastSavedSecondRef =\n    useRef(-1);\n\n  const [locationName, setLocationName] =\n    useState(initialLocationName);\n\n  const [\n    locationTrack,\n    setLocationTrack,\n  ] = useState<PlayableMusicTrack | null>(\n    initialLocationTrack,\n  );\n\n  const [ownedTracks, setOwnedTracks] =\n    useState(initialOwnedTracks);\n\n  const [usePersonal, setUsePersonal] =\n    useState(\n      preferences.usePersonalMusic,\n    );\n\n  const [\n    selectedTrackId,\n    setSelectedTrackId,\n  ] = useState(\n    preferences.selectedTrackId,\n  );\n\n  const [volume, setVolume] =\n    useState(preferences.volume);\n\n  const [muted, setMuted] =\n    useState(preferences.muted);\n\n  const [playing, setPlaying] =\n    useState(false);\n\n  const [\n    needsGesture,\n    setNeedsGesture,\n  ] = useState(false);\n\n  const [expanded, setExpanded] =\n    useState(false);\n\n  const [\n    portalTarget,\n    setPortalTarget,\n  ] = useState<HTMLElement | null>(\n    null,\n  );\n\n  useEffect(() => {\n    let cancelled = false;\n    let frame = 0;\n    let attempts = 0;\n\n    const findTarget = () => {\n      if (cancelled) return;\n\n      const target =\n        document.getElementById(\n          "game-music-context-slot",\n        );\n\n      if (target) {\n        setPortalTarget(target);\n        return;\n      }\n\n      attempts += 1;\n\n      if (attempts < 60) {\n        frame =\n          window.requestAnimationFrame(\n            findTarget,\n          );\n      }\n    };\n\n    findTarget();\n\n    return () => {\n      cancelled = true;\n      window.cancelAnimationFrame(\n        frame,\n      );\n    };\n  }, []);\n\n  const selectedOwned =\n    useMemo(\n      () =>\n        ownedTracks.find(\n          (track) =>\n            track.id ===\n            selectedTrackId,\n        ) ?? null,\n      [\n        ownedTracks,\n        selectedTrackId,\n      ],\n    );\n\n  const personalAvailable =\n    ownedTracks.length > 0;\n\n  const effectivePersonal =\n    usePersonal &&\n    personalAvailable &&\n    selectedOwned !== null;\n\n  /*\n   * Personal music is an override for a location\n   * that has music. No location track = silence.\n   */\n  const activeTrack:\n    | PlayableMusicTrack\n    | null = locationTrack\n      ? effectivePersonal\n        ? selectedOwned\n        : locationTrack\n      : null;\n\n  async function persist(\n    next: {\n      usePersonalMusic?: boolean;\n      selectedTrackId?:\n        | string\n        | null;\n      volume?: number;\n      muted?: boolean;\n    },\n  ) {\n    try {\n      const response = await fetch(\n        "/api/music/preferences",\n        {\n          method: "PATCH",\n          headers: {\n            "Content-Type":\n              "application/json",\n          },\n          body: JSON.stringify({\n            usePersonalMusic:\n              next.usePersonalMusic ??\n              usePersonal,\n            selectedTrackId:\n              next.selectedTrackId !==\n              undefined\n                ? next.selectedTrackId\n                : selectedTrackId,\n            volume:\n              next.volume ?? volume,\n            muted:\n              next.muted ?? muted,\n          }),\n        },\n      );\n\n      if (!response.ok) {\n        const data =\n          (await response.json()) as {\n            error?: string;\n          };\n\n        console.error(\n          data.error ??\n            "Unable to save music preferences.",\n        );\n      }\n    } catch {\n      // A transient navigation/dev-server\n      // interruption can safely retry later.\n    }\n  }\n\n  function clearFade() {\n    if (\n      fadeTimerRef.current !== null\n    ) {\n      window.clearInterval(\n        fadeTimerRef.current,\n      );\n      fadeTimerRef.current = null;\n    }\n  }\n\n  function fadeTo(\n    target: number,\n  ) {\n    const audio = audioRef.current;\n\n    if (!audio) return;\n\n    clearFade();\n\n    const start = audio.volume;\n    const started = Date.now();\n    const duration = 420;\n\n    fadeTimerRef.current =\n      window.setInterval(() => {\n        const progress = Math.min(\n          1,\n          (Date.now() - started) /\n            duration,\n        );\n\n        audio.volume =\n          start +\n          (target - start) *\n            progress;\n\n        if (progress >= 1) {\n          clearFade();\n        }\n      }, 25);\n  }\n\n  function savePosition(\n    trackId: string | null,\n    currentTime?: number,\n  ) {\n    if (\n      !trackId ||\n      typeof window === "undefined"\n    ) {\n      return;\n    }\n\n    const value =\n      currentTime ??\n      audioRef.current?.currentTime ??\n      0;\n\n    if (\n      !Number.isFinite(value) ||\n      value < 0\n    ) {\n      return;\n    }\n\n    try {\n      window.localStorage.setItem(\n        positionKey(trackId),\n        String(value),\n      );\n    } catch {\n      // Storage can be unavailable in\n      // restricted browser modes.\n    }\n  }\n\n  function restorePosition(\n    audio: HTMLAudioElement,\n    trackId: string,\n  ) {\n    try {\n      const raw =\n        window.localStorage.getItem(\n          positionKey(trackId),\n        );\n\n      const saved = Number(raw);\n\n      if (\n        Number.isFinite(saved) &&\n        saved > 0 &&\n        Number.isFinite(\n          audio.duration,\n        ) &&\n        audio.duration > 0\n      ) {\n        audio.currentTime =\n          Math.min(\n            saved,\n            Math.max(\n              0,\n              audio.duration - 0.25,\n            ),\n          );\n      }\n    } catch {\n      // Ignore unavailable local storage.\n    }\n  }\n\n  useEffect(() => {\n    const audio = audioRef.current;\n\n    if (!audio) return;\n\n    const track = activeTrack;\n\n    clearFade();\n\n    if (!track) {\n      audio.pause();\n      setPlaying(false);\n      audio.removeAttribute("src");\n      audio.load();\n      return;\n    }\n\n    lastSavedSecondRef.current = -1;\n\n    audio.pause();\n    audio.src = track.url;\n    audio.loop = true;\n    audio.muted = muted;\n    audio.volume = 0;\n    audio.load();\n\n    void audio\n      .play()\n      .then(() => {\n        setNeedsGesture(false);\n        fadeTo(\n          muted ? 0 : volume,\n        );\n      })\n      .catch(() => {\n        audio.volume = volume;\n        setNeedsGesture(true);\n      });\n\n    return () => {\n      savePosition(\n        track.id,\n        audio.currentTime,\n      );\n      clearFade();\n    };\n  }, [activeTrack?.id]);\n\n  useEffect(() => {\n    const audio = audioRef.current;\n\n    if (!audio) return;\n\n    audio.muted = muted;\n\n    if (\n      fadeTimerRef.current === null\n    ) {\n      audio.volume = volume;\n    }\n  }, [muted, volume]);\n\n  useEffect(() => {\n    if (\n      !needsGesture ||\n      !activeTrack\n    ) {\n      return;\n    }\n\n    const resume = () => {\n      const audio = audioRef.current;\n\n      if (!audio) return;\n\n      void audio\n        .play()\n        .then(() => {\n          setNeedsGesture(false);\n          fadeTo(\n            muted ? 0 : volume,\n          );\n        })\n        .catch(() => {\n          // Dedicated Play remains.\n        });\n    };\n\n    document.addEventListener(\n      "pointerdown",\n      resume,\n      {\n        capture: true,\n        once: true,\n      },\n    );\n\n    document.addEventListener(\n      "keydown",\n      resume,\n      {\n        capture: true,\n        once: true,\n      },\n    );\n\n    return () => {\n      document.removeEventListener(\n        "pointerdown",\n        resume,\n        true,\n      );\n      document.removeEventListener(\n        "keydown",\n        resume,\n        true,\n      );\n    };\n  }, [\n    needsGesture,\n    activeTrack?.id,\n    muted,\n    volume,\n  ]);\n\n  /*\n   * Keep the location assignment live. When\n   * staff removes/disables music, stop it and\n   * remove this UI without a page refresh.\n   */\n  useEffect(() => {\n    let cancelled = false;\n\n    async function refreshCurrentMusic() {\n      try {\n        const known =\n          locationTrack?.id ?? "";\n\n        const response = await fetch(\n          `/api/music/current?known=${encodeURIComponent(\n            known,\n          )}`,\n          {\n            cache: "no-store",\n          },\n        );\n\n        if (\n          !response.ok ||\n          cancelled\n        ) {\n          return;\n        }\n\n        const data =\n          (await response.json()) as CurrentMusicResponse;\n\n        if (cancelled) return;\n\n        if (!data.music?.locationTrack) {\n          const audio =\n            audioRef.current;\n\n          if (audio) {\n            savePosition(\n              activeTrack?.id ?? null,\n              audio.currentTime,\n            );\n            audio.pause();\n          }\n\n          setPlaying(false);\n          setExpanded(false);\n          setLocationTrack(null);\n          return;\n        }\n\n        if (data.locationName) {\n          setLocationName(\n            data.locationName,\n          );\n        }\n\n        const incoming =\n          data.music.locationTrack;\n\n        setLocationTrack(\n          (current) => {\n            if (\n              current?.id ===\n                incoming.id &&\n              !incoming.url\n            ) {\n              return {\n                ...current,\n                name: incoming.name,\n              };\n            }\n\n            return incoming.url\n              ? incoming\n              : current;\n          },\n        );\n\n        if (\n          data.music.ownedTracks\n            .length > 0\n        ) {\n          setOwnedTracks(\n            data.music.ownedTracks,\n          );\n        }\n      } catch {\n        // Temporary network loss should not\n        // stop already-authorised playback.\n      }\n    }\n\n    void refreshCurrentMusic();\n\n    const timer =\n      window.setInterval(\n        () => {\n          if (\n            document.visibilityState ===\n            "visible"\n          ) {\n            void refreshCurrentMusic();\n          }\n        },\n        LIVE_CHECK_MS,\n      );\n\n    const handleFocus = () => {\n      void refreshCurrentMusic();\n    };\n\n    window.addEventListener(\n      "focus",\n      handleFocus,\n    );\n\n    return () => {\n      cancelled = true;\n      window.clearInterval(timer);\n      window.removeEventListener(\n        "focus",\n        handleFocus,\n      );\n    };\n  }, [\n    locationTrack?.id,\n    activeTrack?.id,\n  ]);\n\n  useEffect(\n    () => () => {\n      clearFade();\n      const audio = audioRef.current;\n\n      if (audio) {\n        savePosition(\n          activeTrack?.id ?? null,\n          audio.currentTime,\n        );\n        audio.pause();\n      }\n    },\n    [activeTrack?.id],\n  );\n\n  async function togglePlayback() {\n    const audio = audioRef.current;\n\n    if (!audio || !activeTrack) {\n      return;\n    }\n\n    if (!audio.paused) {\n      savePosition(\n        activeTrack.id,\n        audio.currentTime,\n      );\n      audio.pause();\n      return;\n    }\n\n    try {\n      audio.volume = volume;\n      await audio.play();\n      setNeedsGesture(false);\n    } catch {\n      setNeedsGesture(true);\n    }\n  }\n\n  function chooseMode(\n    personal: boolean,\n  ) {\n    if (\n      personal &&\n      ownedTracks.length === 0\n    ) {\n      return;\n    }\n\n    let nextSelected =\n      selectedTrackId;\n\n    if (\n      personal &&\n      !selectedOwned\n    ) {\n      nextSelected =\n        ownedTracks[0]?.id ?? null;\n      setSelectedTrackId(\n        nextSelected,\n      );\n    }\n\n    setUsePersonal(personal);\n\n    void persist({\n      usePersonalMusic: personal,\n      selectedTrackId:\n        nextSelected,\n    });\n  }\n\n  function chooseTrack(\n    trackId: string,\n  ) {\n    setSelectedTrackId(trackId);\n    setUsePersonal(true);\n\n    void persist({\n      usePersonalMusic: true,\n      selectedTrackId: trackId,\n    });\n  }\n\n  function toggleMute() {\n    const next = !muted;\n    setMuted(next);\n\n    void persist({\n      muted: next,\n    });\n  }\n\n  if (!locationTrack) {\n    return (\n      <audio\n        ref={audioRef}\n        className="hidden"\n      />\n    );\n  }\n\n  const panel = (\n    <section\n      data-sep-interaction-ignore="true"\n      className="mb-3 border border-[rgb(var(--sep-colour-59432c))]/40 bg-[rgb(var(--sep-colour-100c09))]"\n    >\n      <div className="flex h-10 items-center">\n        <button\n          type="button"\n          onClick={() =>\n            setExpanded(\n              (current) => !current,\n            )\n          }\n          aria-expanded={expanded}\n          className="flex min-w-0 flex-1 items-center gap-2 px-3 text-left"\n        >\n          <span className="text-[10px] text-[rgb(var(--sep-colour-a68b67))]">\n            ♫\n          </span>\n\n          <span className="min-w-0 flex-1 truncate text-[8px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-876a46))]">\n            {activeTrack?.name ??\n              "Location Music"}\n          </span>\n\n          {playing ? (\n            <span\n              className="flex h-4 shrink-0 items-end gap-[1px]"\n              aria-hidden="true"\n            >\n              <span className="h-1.5 w-px animate-pulse bg-[rgb(var(--sep-colour-a68b67))]/70" />\n              <span className="h-2.5 w-px animate-pulse bg-[rgb(var(--sep-colour-a68b67))]/80 [animation-delay:160ms]" />\n              <span className="h-1 w-px animate-pulse bg-[rgb(var(--sep-colour-a68b67))]/60 [animation-delay:320ms]" />\n            </span>\n          ) : null}\n\n          <ChevronDown\n            className={`h-3.5 w-3.5 shrink-0 text-[rgb(var(--sep-colour-756957))] transition-transform ${\n              expanded\n                ? "rotate-180"\n                : ""\n            }`}\n          />\n        </button>\n\n        <button\n          type="button"\n          onClick={() =>\n            void togglePlayback()\n          }\n          aria-label={\n            playing\n              ? "Pause location music"\n              : "Play location music"\n          }\n          title={\n            playing\n              ? "Pause"\n              : "Play"\n          }\n          className="flex h-10 w-10 shrink-0 items-center justify-center border-l border-[rgb(var(--sep-colour-59432c))]/40 text-[rgb(var(--sep-colour-c6a26d))] transition hover:bg-[rgb(var(--sep-colour-17110d))] hover:text-[rgb(var(--sep-colour-ead2a5))]"\n        >\n          {playing ? (\n            <Pause className="h-4 w-4" />\n          ) : (\n            <Play className="h-4 w-4" />\n          )}\n        </button>\n\n        <button\n          type="button"\n          onClick={toggleMute}\n          aria-pressed={muted}\n          aria-label={\n            muted\n              ? "Unmute location music"\n              : "Mute location music"\n          }\n          title={\n            muted\n              ? "Unmute"\n              : "Mute"\n          }\n          className={`flex h-10 w-10 shrink-0 items-center justify-center border-l transition ${\n            muted\n              ? "border-red-900/70 bg-red-950/35 text-red-400 hover:border-red-700/80 hover:text-red-300"\n              : "border-[rgb(var(--sep-colour-59432c))]/40 text-[rgb(var(--sep-colour-c6a26d))] hover:bg-[rgb(var(--sep-colour-17110d))] hover:text-[rgb(var(--sep-colour-ead2a5))]"\n          }`}\n        >\n          {muted ? (\n            <VolumeX className="h-4 w-4" />\n          ) : (\n            <Volume2 className="h-4 w-4" />\n          )}\n        </button>\n      </div>\n\n      {expanded ? (\n        <div className="border-t border-[rgb(var(--sep-colour-59432c))]/30 px-3 py-3">\n          <div className="flex items-center justify-between gap-3">\n            <div className="min-w-0">\n              <p className="text-[7px] uppercase tracking-[0.2em] text-[rgb(var(--sep-colour-756957))]">\n                Location Music\n              </p>\n              <p className="mt-1 truncate font-serif text-[13px] text-[rgb(var(--sep-colour-d6bd91))]">\n                {activeTrack?.name}\n              </p>\n              <p className="mt-1 truncate text-[8px] text-[rgb(var(--sep-colour-756957))]">\n                {effectivePersonal\n                  ? "My Music"\n                  : locationName}\n              </p>\n            </div>\n\n            {needsGesture ? (\n              <button\n                type="button"\n                onClick={() =>\n                  void togglePlayback()\n                }\n                className="flex h-8 w-8 shrink-0 items-center justify-center border border-[rgb(var(--sep-colour-80613b))]/70 text-[rgb(var(--sep-colour-d8bf91))]"\n                aria-label="Play location music"\n              >\n                <Play className="h-3.5 w-3.5" />\n              </button>\n            ) : null}\n          </div>\n\n          {personalAvailable ? (\n            <div className="mt-3 space-y-2">\n              <select\n                value={\n                  effectivePersonal\n                    ? "personal"\n                    : "location"\n                }\n                onChange={(event) =>\n                  chooseMode(\n                    event.target\n                      .value ===\n                      "personal",\n                  )\n                }\n                className="w-full border border-[rgb(var(--sep-colour-59432c))]/45 bg-[rgb(var(--sep-colour-0d0907))] px-2.5 py-2 text-[9px] uppercase tracking-[0.1em] text-[rgb(var(--sep-colour-d4bea0))] outline-none focus:border-[rgb(var(--sep-colour-80613b))]"\n              >\n                <option value="location">\n                  Location Music\n                </option>\n                <option value="personal">\n                  My Music\n                </option>\n              </select>\n\n              {effectivePersonal ? (\n                <select\n                  value={\n                    selectedOwned?.id ??\n                    ownedTracks[0]?.id ??\n                    ""\n                  }\n                  onChange={(event) =>\n                    chooseTrack(\n                      event.target.value,\n                    )\n                  }\n                  className="w-full border border-[rgb(var(--sep-colour-59432c))]/45 bg-[rgb(var(--sep-colour-0d0907))] px-2.5 py-2 text-[9px] text-[rgb(var(--sep-colour-d4bea0))] outline-none focus:border-[rgb(var(--sep-colour-80613b))]"\n                >\n                  {ownedTracks.map(\n                    (track) => (\n                      <option\n                        key={track.id}\n                        value={track.id}\n                      >\n                        {track.name}\n                      </option>\n                    ),\n                  )}\n                </select>\n              ) : null}\n            </div>\n          ) : null}\n\n          <label className="mt-3 block">\n            <span className="mb-1.5 block text-[7px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-756957))]">\n              Volume\n            </span>\n            <input\n              type="range"\n              min={0}\n              max={1}\n              step={0.05}\n              value={volume}\n              onChange={(event) =>\n                setVolume(\n                  Number(\n                    event.target.value,\n                  ),\n                )\n              }\n              onPointerUp={() =>\n                void persist({\n                  volume,\n                })\n              }\n              onKeyUp={() =>\n                void persist({\n                  volume,\n                })\n              }\n              className="block h-1.5 w-full cursor-pointer accent-[rgb(var(--sep-colour-a77b43))]"\n            />\n          </label>\n        </div>\n      ) : null}\n    </section>\n  );\n\n  return (\n    <>\n      <audio\n        ref={audioRef}\n        preload="auto"\n        className="hidden"\n        onLoadedMetadata={(event) => {\n          if (activeTrack) {\n            restorePosition(\n              event.currentTarget,\n              activeTrack.id,\n            );\n          }\n        }}\n        onPlay={() => {\n          setPlaying(true);\n          setNeedsGesture(false);\n        }}\n        onPause={() => {\n          setPlaying(false);\n\n          if (activeTrack) {\n            savePosition(\n              activeTrack.id,\n            );\n          }\n        }}\n        onTimeUpdate={(event) => {\n          if (!activeTrack) return;\n\n          const second =\n            Math.floor(\n              event.currentTarget\n                .currentTime,\n            );\n\n          if (\n            second -\n              lastSavedSecondRef.current >=\n            2\n          ) {\n            lastSavedSecondRef.current =\n              second;\n\n            savePosition(\n              activeTrack.id,\n              event.currentTarget\n                .currentTime,\n            );\n          }\n        }}\n      />\n\n      {portalTarget\n        ? createPortal(\n            panel,\n            portalTarget,\n          )\n        : null}\n    </>\n  );\n}\n', encoding='utf-8')
print('  wrote app/(portal)/game/components/RoomMusicPlayer.tsx')
mobile_path.write_text(mobile, encoding='utf-8')
print('  wrote components/portal/mobile-portal-navigation.tsx')
forum_path.write_text(forum, encoding='utf-8')
