route_path.write_text('import {\n  NextRequest,\n  NextResponse,\n} from "next/server";\n\nimport { createAdminClient } from "@/lib/supabase/admin";\nimport { createClient } from "@/lib/supabase/server";\nimport { getCharacterMusicPayload } from "@/lib/music/get-character-music";\n\nexport async function GET(\n  request: NextRequest,\n) {\n  const supabase = await createClient();\n\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) {\n    return NextResponse.json(\n      {\n        error: "Not authenticated.",\n      },\n      {\n        status: 401,\n      },\n    );\n  }\n\n  const {\n    data: character,\n    error: characterError,\n  } = await supabase\n    .from("characters")\n    .select(\n      "id, current_room_id, status",\n    )\n    .eq("user_id", user.id)\n    .maybeSingle();\n\n  if (\n    characterError ||\n    !character ||\n    character.status !== "approved" ||\n    !character.current_room_id\n  ) {\n    return NextResponse.json({\n      locationName: null,\n      music: null,\n    });\n  }\n\n  const admin = createAdminClient();\n\n  const {\n    data: room,\n    error: roomError,\n  } = await admin\n    .from("rooms")\n    .select(\n      "id, name, music_track_id, is_active",\n    )\n    .eq(\n      "id",\n      character.current_room_id,\n    )\n    .maybeSingle();\n\n  if (\n    roomError ||\n    !room ||\n    room.is_active !== true ||\n    !room.music_track_id\n  ) {\n    return NextResponse.json({\n      locationName:\n        room?.name ?? null,\n      music: null,\n    });\n  }\n\n  /*\n   * Confirm the assigned track is still\n   * active. This is the live kill switch.\n   */\n  const {\n    data: track,\n    error: trackError,\n  } = await admin\n    .from("music_tracks")\n    .select("id, name")\n    .eq(\n      "id",\n      room.music_track_id,\n    )\n    .eq("is_active", true)\n    .maybeSingle();\n\n  if (\n    trackError ||\n    !track\n  ) {\n    return NextResponse.json({\n      locationName: room.name,\n      music: null,\n    });\n  }\n\n  const known =\n    request.nextUrl.searchParams.get(\n      "known",\n    );\n\n  /*\n   * If it is still the same active location\n   * track, avoid regenerating signed URLs on\n   * every live heartbeat.\n   */\n  if (known === track.id) {\n    return NextResponse.json({\n      locationName: room.name,\n      music: {\n        locationTrack: {\n          id: track.id,\n          name: track.name,\n          url: "",\n        },\n        ownedTracks: [],\n        preferences: {\n          usePersonalMusic: false,\n          selectedTrackId: null,\n          volume: 0,\n          muted: false,\n        },\n      },\n    });\n  }\n\n  const music =\n    await getCharacterMusicPayload(\n      character.id,\n      room.music_track_id,\n    );\n\n  if (!music.locationTrack) {\n    return NextResponse.json({\n      locationName: room.name,\n      music: null,\n    });\n  }\n\n  return NextResponse.json({\n    locationName: room.name,\n    music,\n  });\n}\n', encoding='utf-8')
